import{_ as s,o as t,c as a,a2 as n}from"./chunks/framework.Boholvbs.js";const h=JSON.parse('{"title":"xsync-output(1)","description":"Read terminal status, capture structured events, and keep file output separate.","frontmatter":{"title":"xsync-output(1)","description":"Read terminal status, capture structured events, and keep file output separate.","manual":"xsync-output(1)","manualName":"Progress & output","sectionNumber":"1"},"headers":[],"relativePath":"progress.md","filePath":"progress.md"}'),o={name:"progress.md"};function r(l,e,i,c,d,p){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="xsync-output-1" tabindex="-1">xsync-output(1) <a class="header-anchor" href="#xsync-output-1" aria-label="Permalink to &quot;xsync-output(1)&quot;">​</a></h1><div class="manual-deck"><strong>Progress &amp; output</strong><p>Read terminal status, capture structured events, and keep file output separate.</p></div><h2 id="streams" tabindex="-1">OUTPUT STREAMS <a class="header-anchor" href="#streams" aria-label="Permalink to &quot;OUTPUT STREAMS {#streams}&quot;">​</a></h2><div class="manual-table-wrap"><table><thead><tr><th scope="col">Stream</th><th scope="col">Contents</th></tr></thead><tbody><tr><td>stderr</td><td>Live progress, JSON progress events, fallback notices, and diagnostics</td></tr><tr><td>stdout</td><td>Listings, verbose/itemized file output, stats, and dry-run summaries</td></tr></tbody></table></div><p>Progress is automatic when stderr is a terminal. Scripts stay quiet unless progress is explicitly requested. <code>--quiet</code> suppresses progress and non-error messages.</p><h2 id="terminal" tabindex="-1">TERMINAL PROGRESS <a class="header-anchor" href="#terminal" aria-label="Permalink to &quot;TERMINAL PROGRESS {#terminal}&quot;">​</a></h2><div class="example-caption">Partial retention plus progress</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aP</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><p>Long-running files receive their own row after 200 ms; quick files share a small-files completion-rate row. The total line includes counts, bytes, throughput, and ETA when known.</p><p>Push progress follows successful receiver writes, rather than merely bytes read or sent. <code>sent … wire</code> is a separate count. With <code>-z</code>, the display adds wire rate and compression ratio; <code>-vv</code> adds a limiting-stage estimate.</p><p><a class="manual-back-link" href="../index.html#demo" target="_self">Replay actual xsync terminal output <span aria-hidden="true">↗</span></a></p><h2 id="phases" tabindex="-1">PHASES <a class="header-anchor" href="#phases" aria-label="Permalink to &quot;PHASES {#phases}&quot;">​</a></h2><div class="manual-table-wrap"><table><thead><tr><th scope="col">Label</th><th scope="col">Meaning</th></tr></thead><tbody><tr><td>scanning</td><td>Discovering entries; totals can still grow</td></tr><tr><td>verifying N checks</td><td>Successful source and destination checksum checks</td></tr><tr><td>cloning path/</td><td>Whole-directory APFS clone in progress</td></tr><tr><td>deleting N</td><td>Destination entries removed</td></tr><tr><td>waiting for receiver</td><td>Push helper is finishing writes or cleanup</td></tr><tr><td>waiting for sender</td><td>Pull helper has not exited</td></tr></tbody></table></div><p>The terminal and its width determine which details fit. <code>TERM=dumb</code> and non-UTF-8 locales use ASCII fallbacks; <code>NO_COLOR</code> disables color escape sequences.</p><h2 id="json" tabindex="-1">JSON EVENTS <a class="header-anchor" href="#json" aria-label="Permalink to &quot;JSON EVENTS {#json}&quot;">​</a></h2><div class="example-caption">Capture real newline-delimited JSON on stderr</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-a</span><span style="color:#DEDEDE;"> --progress=json</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span><span style="color:#DEDEDE;"> 2&gt;</span><span style="color:#DEDEDE;">progress.ndjson</span></span></code></pre></div><p>Events have type <code>progress</code>, <code>file</code>, or <code>complete</code>. Counters are raw integers. Progress records include elapsed milliseconds, planned/completed counts, bytes, wire bytes, phase, and scan/dry-run flags. Completed file events include path and itemization fields; the final event includes success and exit code.</p><aside class="manual-note"><span>NOTE</span><p>Diagnostics can also appear on stderr. Parse JSON event lines explicitly rather than treating every stderr line as JSON. A remote JSON request requires structured file-event support; rsync fallback cannot supply JSON.</p></aside><div class="captured-doc-output"><span class="micro">ACTUAL CAPTURED EVENT</span><pre><code id="actual-json-event">{
  &quot;type&quot;: &quot;progress&quot;,
  &quot;elapsed_ms&quot;: 71,
  &quot;files&quot;: 128,
  &quot;files_total&quot;: 130,
  &quot;bytes&quot;: 103120,
  &quot;bytes_total&quot;: 6460112,
  &quot;files_seen&quot;: 130,
  &quot;wire_bytes&quot;: 0,
  &quot;phase&quot;: &quot;transferring&quot;,
  &quot;deleted&quot;: 0,
  &quot;verified&quot;: 0,
  &quot;scanning&quot;: false,
  &quot;dry_run&quot;: false
}</code></pre><a href="../recordings/progress.ndjson" download>Download the full captured stream ↗</a></div><h2 id="itemization" tabindex="-1">FILE OUTPUT AND LOGS <a class="header-anchor" href="#itemization" aria-label="Permalink to &quot;FILE OUTPUT AND LOGS {#itemization}&quot;">​</a></h2><div class="example-caption">Itemize changes and append stdout to a log</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-ai</span><span style="color:#DEDEDE;"> --out-format=&#39;%i %n%L&#39;</span><span style="color:#DEDEDE;"> --log-file=transfer.log</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><p><code>%i %n %L %l %o %f %b %t %%</code> are supported, including field widths. <code>%b</code> counts file-content bytes before compression; clones, metadata-only changes, and dry runs count zero. This differs from rsync’s protocol-byte accounting.</p><p>When stdout is redirected, file events are sorted by path and buffered until the transfer ends. A terminal receives them as they finish. The log receives the same stdout stream, without extra timestamps or prefixes.</p><h2 id="units" tabindex="-1">UNITS AND PIPES <a class="header-anchor" href="#units" aria-label="Permalink to &quot;UNITS AND PIPES {#units}&quot;">​</a></h2><div class="example-caption">Use 1024-based display units</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-ahhP</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><div class="example-caption">Use the rsync-shaped plain progress stream off a terminal</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-a</span><span style="color:#DEDEDE;"> --info=progress2</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span><span style="color:#DEDEDE;"> 2&gt;</span><span style="color:#DEDEDE;">progress.log</span></span></code></pre></div><p>Default and <code>-h</code> display units use base 1000; <code>-hh</code> uses base 1024. Explicit ordinary <code>--progress</code> prints one plain line per second on pipes. JSON counters always remain unscaled integers.</p>`,31)])])}const E=s(o,[["render",r]]);export{h as __pageData,E as default};
